const __aivicBundle_77_prioritizeChallengeTargets = (() => {
  function prioritizeChallengeTargets(
    reportStatusList: Array<{
      userId?: string;
      employeeId?: string;
      name?: string;
      employeeName?: string;
      reportStatus?: string;
      status?: 'submitted' | 'delayed' | 'not_submitted';
      submittedAt?: Date | null;
      isDelayed?: boolean;
      deadlineAt?: Date;
    }>
  ): Array<{
    userId?: string;
    employeeId?: string;
    priority?: number;
    name?: string;
    employeeName?: string;
    reportStatus?: string;
    status?: 'not_submitted' | 'delayed';
    reason?: string;
    isDelayed?: boolean;
    submittedAt?: Date | null;
    deadlineAt?: Date;
  }> {
    if (!reportStatusList || reportStatusList.length === 0) {
      return [];
    }
  
    const unreported: typeof reportStatusList = [];
    const delayed: typeof reportStatusList = [];
  
    for (const member of reportStatusList) {
      const reportStatus = member.reportStatus || member.status;
      const isDelayed = member.isDelayed ?? false;
  
      if (reportStatus === 'unreported' || member.status === 'not_submitted') {
        unreported.push(member);
      } else if (
        (reportStatus === 'reported' || member.status === 'submitted') &&
        isDelayed
      ) {
        delayed.push(member);
      }
    }
  
    const result: Array<{
      userId?: string;
      employeeId?: string;
      priority?: number;
      name?: string;
      employeeName?: string;
      reportStatus?: string;
      status?: 'not_submitted' | 'delayed';
      reason?: string;
      isDelayed?: boolean;
      submittedAt?: Date | null;
      deadlineAt?: Date;
    }> = [];
  
    for (const member of unreported) {
      result.push({
        userId: member.userId,
        employeeId: member.employeeId,
        priority: 1,
        name: member.name,
        employeeName: member.employeeName,
        reportStatus: member.reportStatus || 'unreported',
        status: 'not_submitted',
        reason: '報告がまだ提出されていません',
        isDelayed: member.isDelayed,
        submittedAt: member.submittedAt,
        deadlineAt: member.deadlineAt,
      });
    }
  
    for (const member of delayed) {
      result.push({
        userId: member.userId,
        employeeId: member.employeeId,
        priority: 2,
        name: member.name,
        employeeName: member.employeeName,
        reportStatus: member.reportStatus || 'reported',
        status: 'delayed',
        reason: '報告が期限を超過しています',
        isDelayed: member.isDelayed,
        submittedAt: member.submittedAt,
        deadlineAt: member.deadlineAt,
      });
    }
  
    return result;
  }
  return { prioritizeChallengeTargets };
})();
export const prioritizeChallengeTargets = __aivicBundle_77_prioritizeChallengeTargets.prioritizeChallengeTargets;
/* AIVIC_FUNCTION_BUNDLE_END owner=prioritizeChallengeTargets */

