/* AIVIC_FUNCTION_BUNDLE_START owner=getDelayedReporters exports=getDelayedReporters */
const __aivicBundle_104_getDelayedReporters = (() => {
  function getDelayedReporters(
    reportSubmissions: Array<{
      user_id?: string;
      employeeId?: string;
      user_name?: string;
      employeeName?: string;
      report_submitted_at?: Date | null;
      submittedAt?: Date | null;
      [key: string]: unknown;
    }>,
    now: Date,
    reportDeadlineTime: Date,
  ): Array<{
    user_id?: string;
    employeeId?: string;
    user_name?: string;
    employeeName?: string;
    status: 'not_submitted' | 'delayed';
    delayMinutes?: number;
  }> {
    if (now === undefined || now === null) {
      throw new Error("now is required");
    }
    if (reportDeadlineTime === undefined || reportDeadlineTime === null) {
      throw new Error("reportDeadlineTime is required");
    }
  
    const delayedReporters: Array<{
      user_id?: string;
      employeeId?: string;
      user_name?: string;
      employeeName?: string;
      status: 'not_submitted' | 'delayed';
      delayMinutes?: number;
    }> = [];
  
    for (const submission of reportSubmissions) {
      const submittedAt = submission.report_submitted_at ?? submission.submittedAt;
      const userId = submission.user_id ?? submission.employeeId;
      const userName = submission.user_name ?? submission.employeeName;
  
      if (submittedAt === null || submittedAt === undefined) {
        const entry: {
          user_id?: string;
          employeeId?: string;
          user_name?: string;
          employeeName?: string;
          status: 'not_submitted' | 'delayed';
          delayMinutes?: number;
        } = {
          status: 'not_submitted',
        };
  
        if (submission.user_id !== undefined) {
          entry.user_id = userId as string;
        }
        if (submission.employeeId !== undefined) {
          entry.employeeId = userId as string;
        }
        if (submission.user_name !== undefined) {
          entry.user_name = userName as string;
        }
        if (submission.employeeName !== undefined) {
          entry.employeeName = userName as string;
        }
  
        delayedReporters.push(entry);
        continue;
      }
  
      if (submittedAt > reportDeadlineTime) {
        const delayMs = submittedAt.getTime() - reportDeadlineTime.getTime();
        const delayMinutes = Math.ceil(delayMs / (1000 * 60));
  
        const entry: {
          user_id?: string;
          employeeId?: string;
          user_name?: string;
          employeeName?: string;
          status: 'not_submitted' | 'delayed';
          delayMinutes?: number;
        } = {
          status: 'delayed',
          delayMinutes,
        };
  
        if (submission.user_id !== undefined) {
          entry.user_id = userId as string;
        }
        if (submission.employeeId !== undefined) {
          entry.employeeId = userId as string;
        }
        if (submission.user_name !== undefined) {
          entry.user_name = userName as string;
        }
        if (submission.employeeName !== undefined) {
          entry.employeeName = userName as string;
        }
  
        delayedReporters.push(entry);
      }
    }
  
    return delayedReporters;
  }
  return { getDelayedReporters };
})();
export const getDelayedReporters = __aivicBundle_104_getDelayedReporters.getDelayedReporters;
/* AIVIC_FUNCTION_BUNDLE_END owner=getDelayedReporters */

/* AIVIC_FUNCTION_BUNDLE_START owner=classifyReportArrivalStatus exports=classifyReportArrivalStatus */
const __aivicBundle_105_classifyReportArrivalStatus = (() => {
  function classifyReportArrivalStatus(
    reportSubmissions: Array<{
      user_id?: string;
      employeeId?: string;
      submitted_at?: Date | null;
      submittedAt?: Date;
      employeeName?: string;
    }>,
    reportDeadlineTime: Date
  ): {
    arrived: Array<{ user_id: string; submitted_at: Date }>;
    not_arrived: Array<{ user_id: string; submitted_at: null }>;
    delayed: Array<{ user_id: string; submitted_at: Date }>;
  } {
    const arrived: Array<{ user_id: string; submitted_at: Date }> = [];
    const not_arrived: Array<{ user_id: string; submitted_at: null }> = [];
    const delayed: Array<{ user_id: string; submitted_at: Date }> = [];
  
    for (const report of reportSubmissions) {
      const userId = (report.user_id || report.employeeId || "") as string;
      const submittedAt = (report.submitted_at ?? report.submittedAt ?? null) as Date | null;
  
      if (submittedAt === null || submittedAt === undefined) {
        not_arrived.push({ user_id: userId, submitted_at: null });
      } else if (submittedAt <= reportDeadlineTime) {
        arrived.push({ user_id: userId, submitted_at: submittedAt });
      } else {
        delayed.push({ user_id: userId, submitted_at: submittedAt });
      }
    }
  
    return {
      arrived,
      not_arrived,
      delayed,
    };
  }
  return { classifyReportArrivalStatus };
})();
